using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("api_fetch"), Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The API path to call (e.g. /users/1).")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("api");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Summarizes the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional desired length (e.g. 'short', 'detailed').")] string? style = "short")
    {
        return
        [
            new(Role.User,
                $"Summarize the following text. Style: {style}.\n\n{text}")
        ];
    }
}

