using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Summarizes the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional desired length (e.g. 'short', 'detailed').")] string? style = "short")
    {
        return
        [
            new(Role.User,
                $"Summarize the following text. Style: {style}.\n\n{text}")
        ];
    }
}

